corrected_code:
router.post('/api/cart/merge', verifyCustomerJwt, async (req, res) => {
  const { guestSessionId } = req.body;
  const cookieGuestId = req.signedCookies['guest_session_id'];

  if (!cookieGuestId || cookieGuestId !== guestSessionId) {
    return res.status(403).json({ error: 'Invalid or mismatched guest session cookie' });
  }

  const userCartKey = `cart:user:${req.user.id}`;
  const guestCartKey = `cart:guest:${guestSessionId}`;

  const guestItems = await redis.smembers(guestCartKey);
  if (guestItems.length > 0) {
    await redis.sadd(userCartKey, ...guestItems);
    await redis.del(guestCartKey);
  }

  res.clearCookie('guest_session_id');
  const merged = await redis.smembers(userCartKey);
  res.json({ cart: merged });
});
